data.minimal_example:
final stock = Stock<String, List<Tweet>>(
    fetcher: fetcher,
    sourceOfTruth: sourceOfTruth,
);

stock.stream('user_id', refresh: true).listen((response) {
  response.when(
    onLoading: (origin) => print('Loading...'),
    onData: (origin, data) => print('Data: $data'),
    onError: (origin, error, stacktrace) => print('Error: $error'),
  );
});
